Game.prototype.clearLanding=function(x,y,ignore=-1){if(x<38||x>C.W-38||y<42||y+20>=this.water)return false;for(let dx=-12;dx<=12;dx+=6)for(let dy=-36;dy<=14;dy+=5)if(this.solid(x+dx,y+dy))return false;return this.alive().every(u=>u.id===ignore||Math.hypot(u.x-x,u.y-y)>48);};
