const create=C.createBattle;C.createBattle=function(o={}){const g=create(o),seed=root.crypto?.getRandomValues?root.crypto.getRandomValues(new Uint32Array(1))[0]:(Date.now()+Math.random()*4294967295)>>>0,rng=C.random(seed),sites=g.landingSites(),chosen=[];g.options.spawnSeed=seed;for(let n=0;n<6;n++){const available=sites.filter(p=>chosen.every(q=>Math.hypot(p.x-q.x,p.y-q.y)>155));if(!available.length)break;chosen.push(available[Math.floor(rng()*available.length)]);}if(chosen.length===6){const order=[...g.units];for(let i=order.length-1;i>0;i--){const j=Math.floor(rng()*(i+1));[order[i],order[j]]=[order[j],order[i]];}order.forEach((u,i)=>Object.assign(u,chosen[i],{vx:0,vy:0,grounded:true,face:chosen[i].x<800?1:-1,groundTilt:0}));g.angle=g.worldAim?g.worldAim(g.elevation||45):g.active.face>0?45:135;}g.ammo.forEach(a=>a[ROPE]=null);return g;};
const check=Game.prototype.checkWin;Game.prototype.checkWin=function(){if(this.phase==='ended'&&Number.isInteger(this.winner))return true;return check.call(this);};
// Intersect the complete visible silhouette along the segment, rather than only its endpoint.
function circleT(x,y,dx,dy,cx,cy,r){const ox=x-cx,oy=y-cy,a=dx*dx+dy*dy,c=ox*ox+oy*oy-r*r;if(c<=0)return 0;if(!a)return Infinity;const b=2*(ox*dx+oy*dy),disc=b*b-4*a*c;if(disc<0)return Infinity;const t=(-b-Math.sqrt(disc))/(2*a);return t>=0&&t<=1?t:Infinity;}
Game.prototype.advanceProjectile=function(p,dt,predict=false){const w=WEAPONS[p.weapon];p.age+=dt;if(!p.stuck){p.vx+=this.wind*(w.wind||0)*dt;if(w.kind!=='sniper')p.vy+=(this.options.layout===17?180:290)*dt;if(w.kind==='disc'&&p.age>.55){const owner=this.units[p.owner];if(owner)p.vx+=clamp((owner.x-p.x)*3-p.vx,-1100,1100)*dt;}const dx=p.vx*dt,dy=p.vy*dt,nx=p.x+dx,ny=p.y+dy;let terrain=Infinity,body=Infinity;const n=Math.max(1,Math.ceil(Math.hypot(dx,dy)/.65));for(let i=0;i<=n;i++)if(this.solid(p.x+dx*i/n,p.y+dy*i/n)){terrain=i/n;break;}for(const u of this.alive()){if(u.id===p.owner&&p.age<.12)continue;for(const [cx,cy,r]of [[u.x+(u.face||1)*4,u.y-25,17],[u.x,u.y-12,15],[u.x,u.y+2,15],[u.x-(u.face||1)*12,u.y+9,13]])body=Math.min(body,circleT(p.x,p.y,dx,dy,cx,cy,r));}const t=Math.min(terrain,body),hit=t<=1;if(p.drilling){p.x=nx;p.y=ny;p.drilling-=dt;if(p.drilling<=0)return 'explode';}else if(hit){const hx=p.x+dx*t,hy=p.y+dy*t;if(w.kind==='drill'&&terrain<=body){p.drilling=.24;p.x=nx;p.y=ny;}else if(w.kind==='sticky'){p.x=hx;p.y=hy;p.stuck=true;p.vx=p.vy=0;}else if(w.fuse||p.child){if(body<terrain){p.vx*=-.5;p.vy=-Math.max(45,Math.abs(p.vy)*.45);}else if(this.solid(hx,p.y))p.vx*=-.55;else p.vy*=-.5;p.vx*=.82;p.bounces=(p.bounces||0)+1;if(!predict&&p.bounces<8)this.emit('bounce',{x:p.x,y:p.y});}else{p.x=hx;p.y=hy;return 'explode';}}else{p.x=nx;p.y=ny;}}
if(p.x< -50||p.x>C.W+50||p.y>this.water)return 'water';if(p.age>10||(p.child?p.age>=1.05:w.fuse&&p.age>=w.fuse))return 'explode';return null;};
Game.prototype.teleportDestination=function(point){const sites=this.landingSites();return sites.filter(p=>this.clearLanding(p.x,p.y,this.activeId)).sort((a,b)=>Math.hypot(a.x-point.x,(a.y-point.y)*1.2)-Math.hypot(b.x-point.x,(b.y-point.y)*1.2))[0]||null;};
Game.prototype.setTeleportTarget=function(x,y){const p=this.teleportDestination({x,y});if(!p||Math.hypot(p.x-x,p.y-y)>140){this.emit('message',{text:'비어 있는 지형의 윗면을 선택해 주세요.'});return false;}this.teleportTarget=p;this.emit('message',{text:'도착 지점 선택 완료! 사용 버튼으로 즉시 이동합니다.'});return true;};
Game.prototype.shootRope=function(){if(!this.canFire()||this.charging)return false;if(this.rope)return this.releaseRope();if(this.hook){this.hook=null;return true;}if(this.fuel<8)return false;const u=this.active,a=this.angle*Math.PI/180;this.hook={x:u.x,y:u.y-14,dx:Math.cos(a),dy:-Math.sin(a),travel:0,id:u.id};this.emit('ropeShoot',{id:u.id,x:u.x,y:u.y});return true;};
const step=Game.prototype.step;Game.prototype.step=function(dt=C.STEP){if(!this.paused&&this.phase!=='ended'){const h=this.hook;if(h){const u=this.units[h.id];if(this.phase!=='aim'||u.hp<=0||this.weapon!==ROPE)this.hook=null;else{const distance=Math.min(1050*dt,560-h.travel);let hit=false;for(let d=0;d<=distance;d+=2){const x=h.x+h.dx*d,y=h.y+h.dy*d;if(this.solid(x,y)){const length=Math.hypot(u.x-x,u.y-y);if(length>40){this.rope={x,y,length,restLength:Math.max(55,length-22),angle:Math.atan2(u.x-x,u.y-y),omega:(u.vx*Math.cos(Math.atan2(u.x-x,u.y-y))-u.vy*Math.sin(Math.atan2(u.x-x,u.y-y)))/length,id:u.id,radial:0};u.grounded=false;this.fuel=Math.max(0,this.fuel-8);this.emit('ropeAttach',{id:u.id,x,y});}hit=true;break;}}h.x+=h.dx*distance;h.y+=h.dy*distance;h.travel+=distance;if(hit||h.travel>=560||h.y<0||h.x<0||h.x>C.W){this.hook=null;if(!hit)this.emit('message',{text:'갈고리가 닿지 않았어요. 가까운 구조물을 겨냥하세요.'});}}}for(const u of this.units)if(u.landing){u.landing.time+=dt;if(u.landing.time>=u.landing.duration||!u.grounded||u.hp<=0)delete u.landing;}}return step.call(this,dt);};
const unit=Game.prototype.stepUnit;Game.prototype.stepUnit=function(u,dt){const before={grounded:u.grounded,y:u.y,vy:u.vy};if(!u.grounded)u.fallTop=Math.min(u.fallTop??u.y,u.y);const r=this.rope;if(r?.id===u.id){r.restLength=clamp((r.restLength??r.length)+(this.ropeAdjust||0)*85*dt,55,500);r.radial=(r.radial||0)+((r.restLength-r.length)*28-(r.radial||0)*7)*dt;r.length=clamp(r.length+r.radial*dt,55,540);const adjust=this.ropeAdjust;this.ropeAdjust=0;unit.call(this,u,dt);this.ropeAdjust=adjust;}else{const input=this.input;if(u.landing&&u.id===this.activeId)this.input=0;unit.call(this,u,dt);this.input=input;}if(!before.grounded&&u.grounded&&u.hp>0){const distance=u.y-(u.fallTop??before.y);if(distance>78&&before.vy>230){u.landing={time:0,duration:1.15,height:distance};this.emit('headLand',{id:u.id,x:u.x,y:u.y+18});}delete u.fallTop;}else if(before.grounded&&u.grounded)delete u.fallTop;};
