const canMove=Game.prototype.canMove,canFire=Game.prototype.canFire;Game.prototype.canMove=function(){return !this.active?.landing&&canMove.call(this);};Game.prototype.canFire=function(){return !this.active?.landing&&canFire.call(this);};
