const fire=Game.prototype.fire;Game.prototype.fire=function(a=this.angle,p=this.power,internal=false){if(this.weapon===ROPE)return this.shootRope();if(WEAPONS[this.weapon].kind!=='blink')return fire.call(this,a,p,internal);if(!this.canFire()||this.weaponLock?.(this.weapon)||this.ammo[this.team][this.weapon]===0)return false;let target=this.teleportTarget;if(!target){const end=this.predict(a,p,0).at(-1);target=end&&this.teleportDestination(end);}if(!target||!this.clearLanding(target.x,target.y,this.activeId)){this.emit('message',{text:'이동할 지형을 화면에서 먼저 선택해 주세요.'});return false;}const u=this.active,from={x:u.x,y:u.y};if(this.rope)this.releaseRope();this.hook=null;Object.assign(u,target,{vx:0,vy:0,grounded:true});delete u.landing;delete u.fallTop;this.ammo[this.team][this.weapon]--;this.stats.shots++;this.phase='retreat';this.retreatClock=4;this.input=0;this.teleportTarget=null;this.emit('teleport',{id:u.id,...target,from});this.emit('fire',{id:u.id,...target,weapon:this.weapon});return true;};
